-- Targeted catalogue content repair. Requires explicit approval for the shared live database.
-- Run in a transaction. No thresholds, formulas, facts, grades, saves or IDs are modified.
-- Idempotent; rejects content changed since the reviewed snapshot.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='education:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ללא פסיכומטרי: ממוצע בגרות 102 לפחות; או בגרות מלאה עם 5 יחידות באנגלית ו־4 יחידות במתמטיקה בציון 80 לפחות בכל אחד.','אפיק נוסף: פסיכומטרי 620 לפחות ובגרות מלאה.','באפיק ציון ההתאמה: 550 לפחות וגם פסיכומטרי 540 לפחות.','אפשר לקבל 5 נקודות בונוס לציון ההתאמה על קורס מקוון מוכר אחד, או 10 על שניים, בציון 80 לפחות בכל קורס.','ללא פסיכומטרי אפשר גם עם ממוצע בגרות 97 ושני קורסים מקוונים מוכרים בציון 80 לפחות בכל אחד.','לבעלי לימודים קודמים: תואר ראשון בממוצע 80 לפחות, או 30 שעות סמסטריאליות לפחות בממוצע 85, ממוסד מוכר.','יש לעמוד בדרישות האוניברסיטה לבגרות או לתעודה שקולה, לעברית ולאנגלית.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: education:tau';
  END IF;
  UPDATE admission_requirements SET specific_admission_notes=ARRAY['ללא פסיכומטרי: ממוצע בגרות 102 לפחות; או בגרות מלאה עם 5 יחידות באנגלית ו־4 יחידות במתמטיקה בציון 80 לפחות בכל אחד.','אפיק נוסף: פסיכומטרי 620 לפחות ובגרות מלאה.','באפיק ציון ההתאמה: 550 לפחות וגם פסיכומטרי 540 לפחות.','אפשר לקבל 5 נקודות בונוס לציון ההתאמה על קורס מקוון מוכר אחד, או 10 על שניים, בציון 80 לפחות בכל קורס.','ללא פסיכומטרי אפשר גם עם ממוצע בגרות 97 ושני קורסים מקוונים מוכרים בציון 80 לפחות בכל אחד.','לבעלי לימודים קודמים: תואר ראשון בממוצע 80 לפחות, או 30 שעות סמסטריאליות לפחות בממוצע 85, ממוסד מוכר.','יש לעמוד בדרישות האוניברסיטה לבגרות או לתעודה שקולה, לעברית ולאנגלית.']::text[] WHERE id='education:tau';
  IF NOT EXISTS (SELECT 1 FROM source_urls WHERE id='education:tau:program' AND ((url IS NOT DISTINCT FROM 'https://www.tau.ac.il') OR (url IS NOT DISTINCT FROM 'https://go.tau.ac.il/he/education/ba?v=requirements'))) THEN
    RAISE EXCEPTION 'Content changed since review: education:tau:program';
  END IF;
  UPDATE source_urls SET url='https://go.tau.ac.il/he/education/ba?v=requirements' WHERE id='education:tau:program';
  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='tau_business:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['פסיכומטרי 640 לפחות וממוצע בגרות 95 לפחות; או פסיכומטרי 680 לפחות וזכאות לבגרות.','אפיק ציון התאמה ניהול: 610 לפחות, ובנוסף פסיכומטרי 620 לפחות או ציון פמ״א 835 לפחות.','ללא פסיכומטרי: בגרות 104 לפחות, אנגלית 5 יחידות בציון 85, מתמטיקה 5 יחידות בציון 70 או 4 בציון 90, ושני קורסים מקוונים בציון 85 לפחות בכל אחד.','הקורסים באפיק ללא פסיכומטרי הם הכרת דוחות כספיים וצעדים ראשונים במדעי המחשב ותכנות בפייתון. ציוני המקצועות באפיק זה הם ללא בונוסים.','דרישת המתמטיקה הכללית: 4 יחידות לפחות בציון עובר, או 140 לפחות בפרק הכמותי בפסיכומטרי.','השכלה אקדמית קודמת: לפחות 30 שעות סמסטריאליות בממוצע 85 במוסד מוכר, וגם פסיכומטרי 640 לפחות.','קורס מקוון מוכר בציון 85 יכול להוסיף 5 נקודות לציון ההתאמה; שניים יכולים להוסיף 10. יתר דרישות האפיק נשארות בתוקף.','הלימודים דו־חוגיים: יש לעמוד גם בתנאי החוג השני, בדרישות השפה והבגרות ובכללים הנוגעים ללימודים אקדמיים קודמים. ההרשמה היא לסמסטר א׳ בלבד.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: tau_business:tau';
  END IF;
  UPDATE admission_requirements SET specific_admission_notes=ARRAY['פסיכומטרי 640 לפחות וממוצע בגרות 95 לפחות; או פסיכומטרי 680 לפחות וזכאות לבגרות.','אפיק ציון התאמה ניהול: 610 לפחות, ובנוסף פסיכומטרי 620 לפחות או ציון פמ״א 835 לפחות.','ללא פסיכומטרי: בגרות 104 לפחות, אנגלית 5 יחידות בציון 85, מתמטיקה 5 יחידות בציון 70 או 4 בציון 90, ושני קורסים מקוונים בציון 85 לפחות בכל אחד.','הקורסים באפיק ללא פסיכומטרי הם הכרת דוחות כספיים וצעדים ראשונים במדעי המחשב ותכנות בפייתון. ציוני המקצועות באפיק זה הם ללא בונוסים.','דרישת המתמטיקה הכללית: 4 יחידות לפחות בציון עובר, או 140 לפחות בפרק הכמותי בפסיכומטרי.','השכלה אקדמית קודמת: לפחות 30 שעות סמסטריאליות בממוצע 85 במוסד מוכר, וגם פסיכומטרי 640 לפחות.','קורס מקוון מוכר בציון 85 יכול להוסיף 5 נקודות לציון ההתאמה; שניים יכולים להוסיף 10. יתר דרישות האפיק נשארות בתוקף.','הלימודים דו־חוגיים: יש לעמוד גם בתנאי החוג השני, בדרישות השפה והבגרות ובכללים הנוגעים ללימודים אקדמיים קודמים. ההרשמה היא לסמסטר א׳ בלבד.']::text[] WHERE id='tau_business:tau';
  IF NOT EXISTS (SELECT 1 FROM source_urls WHERE id='tau_business:tau:program' AND ((url IS NOT DISTINCT FROM 'https://www.tau.ac.il') OR (url IS NOT DISTINCT FROM 'https://go.tau.ac.il/he/management/ba/management?v=requirements'))) THEN
