  END IF;
  UPDATE source_urls SET url='https://go.tau.ac.il/he/management/ba/management?v=requirements' WHERE id='tau_business:tau:program';
  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='tau_accounting:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['פסיכומטרי 640 לפחות וממוצע בגרות 95 לפחות; או פסיכומטרי 680 לפחות וזכאות לבגרות.','אפיק ציון התאמה ניהול: 610 לפחות, ובנוסף פסיכומטרי 620 לפחות או ציון פמ״א 835 לפחות.','ללא פסיכומטרי: בגרות 104 לפחות, אנגלית 5 יחידות בציון 85, מתמטיקה 5 יחידות בציון 70 או 4 בציון 90, ושני קורסים מקוונים בציון 85 לפחות בכל אחד.','הקורסים באפיק ללא פסיכומטרי הם הכרת דוחות כספיים וצעדים ראשונים במדעי המחשב ותכנות בפייתון. ציוני המקצועות באפיק זה הם ללא בונוסים.','דרישת המתמטיקה הכללית: 4 יחידות לפחות בציון עובר, או 140 לפחות בפרק הכמותי בפסיכומטרי.','השכלה אקדמית קודמת: לפחות 30 שעות סמסטריאליות בממוצע 85 במוסד מוכר, וגם פסיכומטרי 630 לפחות.','קורס מקוון מוכר בציון 85 יכול להוסיף 5 נקודות לציון ההתאמה; שניים יכולים להוסיף 10. יתר דרישות האפיק נשארות בתוקף.','הלימודים דו־חוגיים: יש לעמוד גם בתנאי החוג השני, בדרישות השפה והבגרות ובכללים הנוגעים ללימודים אקדמיים קודמים. ההרשמה היא לסמסטר א׳ בלבד.','אפיק נוסף ללא פסיכומטרי: תואר ראשון או שני ממוסד מוכר בממוצע 85 לפחות. בעלי תואר שני במנהל עסקים ממוסד מוכר בארץ יכולים לעמוד באמצעותו בדרישת המתמטיקה.']::text[]))) THEN
