  IF NOT EXISTS (SELECT 1 FROM source_urls WHERE id='tau_accounting:tau:program' AND ((url IS NOT DISTINCT FROM 'https://www.tau.ac.il') OR (url IS NOT DISTINCT FROM 'https://go.tau.ac.il/he/management/ba/accounting?v=admission-requirements'))) THEN
