  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='political_science:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ללא פסיכומטרי: ממוצע בגרות 102 לפחות.','אפיק נוסף: פסיכומטרי 680 לפחות וזכאות לבגרות.','באפיק ציון ההתאמה: 535 לפחות. קורסים מקוונים מוכרים בציון 80 יכולים להוסיף 5 נקודות לקורס אחד או 10 לשניים.','ללא פסיכומטרי אפשר גם עם בגרות 97 ושני קורסים מקוונים בציון 85, אחד מכל מקבץ המוגדר באתר החוג.','לבעלי תואר קודם ממוסד מוכר: תואר ראשון בממוצע 80, או תואר שני בממוצע 85. תואר ראשון בממוצע נמוך מ־80 דורש גם פסיכומטרי 600 לפחות.','השכלה חלקית: לפחות 30 שעות סמסטריאליות בממוצע 85 ממוסד מוכר, וגם פסיכומטרי 520 לפחות.','יש לעמוד בדרישות האוניברסיטה ובתנאי החוג השני בשילוב דו־חוגי. באפיק המעבר מהאוניברסיטה הפתוחה נדרשת אנגלית ברמת מתקדמים ב׳ עד תחילת הלימודים.']::text[]))) THEN
