  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='tau_law:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ציון התאמה 647 לפחות וגם פסיכומטרי 600 לפחות.','אפיק נוסף: פסיכומטרי 700 לפחות וזכאות לבגרות.','לבעלי תואר ראשון: ציון משולב 1475 לפחות וגם פסיכומטרי 600 לפחות; הציון המשולב הוא ממוצע התואר כפול 10, בתוספת הפסיכומטרי הרב־תחומי.','ציון 85 בקורס צמיחה כלכלית וצדק חלוקתי מוסיף 3 נקודות להתאמה. ציון 85 גם בקורס מקוון נוסף מהרשימה מזכה בתוספת כוללת של 5 נקודות.','בקבלה חריגה ללא פסיכומטרי נדרשים קורות חיים, חיבור מקורי על סוגיה משפטית עד 300 מילים, ולבעלי תואר גם גיליון ציונים ואישור זכאות. יש להגישם בתוך שלושה שבועות מהרישום ולעדכן את ועדת הקבלה.','יש לעמוד בדרישות האוניברסיטה. המועד האחרון לקורסים המקוונים במחזור תשפ״ז היה יוני 2026; ספי הקבלה ומועדי הרישום עשויים להשתנות.']::text[]))) THEN
