  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='nursing:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['פסיכומטרי 510 לפחות וציון התאמה 521 לפחות, בצירוף מבדק התאמה למקצוע טיפולי. ייתכן גם ריאיון אישי.','ללא פסיכומטרי: זכאות לבגרות, אנגלית 5 יחידות בציון 90 לפחות, ושני קורסים מקוונים מוכרים בציון 85 לפחות בכל אחד.','לבעלי תואר ראשון מוכר: פסיכומטרי 500 לפחות. השכלה חלקית בהיקף 30 שעות סמסטריאליות בממוצע 85 (84.50) דורשת פסיכומטרי 510 לפחות.','קורס מקוון מוכר בציון 80 מוסיף 10 נקודות להתאמה; שניים מוסיפים 20. הקורסים הם מבוא לפסיכולוגיה, וירוסים, מבוא לכימיה כללית והמוח — המכונה המופלאה מכולם.','נדרשת אנגלית ברמת מתקדמים א׳ ועברית ברמה ג׳ לפי מועדי האוניברסיטה. הקבלה היא לשנה א׳ בלבד.','אין להתקבל לאחר הפסקת לימודי אחיוּת בישראל מסיבות אקדמיות או משמעתיות. המבדק בתשלום ותקף לשנתיים; ועדת הקבלה קובעת את ההתאמה הסופית.','קיימים מסלולי קבלה חריגה לפי בגרות ורקע רפואי, במכסה מוגבלת ובפנייה למזכירות; פירוט מלא בקישור למוסד.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: nursing:tau';
  END IF;
