  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='communication:haifa' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['סכם 550 לפחות; ציונים 500–549 נמצאים בטווח ההמתנה.','ללא פסיכומטרי: בגרות מלאה מאפשרת כניסה למסלול אופק, שבו יש לעבור 2–3 קורסים בציון 70 לפחות בסמסטר הראשון. הקבלה לתואר מותנית בהשלמת המסלול.','נדרשת אנגלית ברמת טרום בסיסי לפחות ועברית 95 לפחות ביעלנט או במבחן הסיווג של האוניברסיטה; יש להשלים עברית 120 בשנה א׳. אפשר לעמוד בדרישת העברית גם בקורס עברית באקדמיה במכינה.','במסלול הדו־חוגי בשנתיים נדרשות אנגלית ברמת בסיסי ועברית 120 כבר בקבלה.','מכינת אוניברסיטת חיפה: ממוצע 90 לקבלה ישירה; 86–89 בצירוף בחינת כניסה בציון 75; מתחת ל־86 דרך מסלול אופק. דרישות השפה חלות גם באפיקים אלה.','סכם 500–549 מאפשר גם מסלול אופק או בחינת כניסה בציון 75, בכפוף לדרישות השפה.','לבעלי תואר קודם מוכר: ממוצע 80 לפחות, או בחינת כניסה בציון 75, או ציון גמר ב־15% העליונים במחזור. מעבר מחוג אחר דורש לפחות 30 נקודות זכות בתקשורת בממוצע 75.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: communication:haifa';
  END IF;
