  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='haifa_infosystems:haifa' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['סכם 680 לפחות; ציונים 650–679 נמצאים בטווח ההמתנה.','מתמטיקה: 4 יחידות בציון 80 לפחות או 5 יחידות בציון 70 לפחות.','נדרשת אנגלית ברמת טרום בסיסי לפחות ועברית 120 ביעלנט או במבחן הסיווג, או השלמת קורס עברית באקדמיה במכינה.','במסלול אופק: סכם 630–679 ועמידה בדרישות המתמטיקה והשפה; ייתכנו בחינת כניסה או ריאיון. יש לעבור 3 קורסים בממוצע משוקלל 70 לפחות בסמסטר הראשון כדי להתקבל מן המניין.','מכינת אוניברסיטת חיפה מאפשרת מסלול אופק עם ממוצע 90, מתמטיקה ברמת 4 יחידות בציון 80, אנגלית ברמת בסיסי ועברית 120.','לזכאים לאפיק המילואים, כוחות הביטחון והמפונים: מסלול אופק עם בגרות מלאה ועמידה בדרישות המתמטיקה והשפה, בפנייה למזכירות. חריגים עשויים להיבחן בריאיון.','קיים אפיק מעבר מהאוניברסיטה הפתוחה ללא פסיכומטרי. בעלי ממוצע 70 לפחות בשנה א׳ במדעי המחשב, מערכות מידע או תחום טכנולוגי במוסד מוכר יכולים לפנות לוועדת חריגים; הקבלה לפי שיקול דעתה.']::text[]))) THEN
