  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='occupational_therapy:haifa' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['סכם 610 לפחות לזימון למיון; בטווח 595–609 הזימון נתון לשיקול דעת החוג.','נדרשת אנגלית ברמת מתקדמים א׳ לפחות ועברית 120 ביעלנט או במבחן הסיווג, או השלמת קורס עברית באקדמיה במכינה.','המיון כולל ריאיון בכתב ולאחר מעברו ריאיון אישי עם שני אנשי סגל. אין קבלה על תנאי, ועמידה בספים אינה מבטיחה קבלה.','אפיקים נוספים למיון: תואר קודם מוכר בממוצע 85, או מכינת מדעים בחיפה בממוצע 90, או מכינת חברה ורוח בחיפה בממוצע 92.','לזכאים לאפיק המילואים, כוחות הביטחון והמפונים: בגרות 100 לפחות ומתמטיקה 3 יחידות בציון 90, 4 בציון 80 או 5 בציון 70. נדרשות גם דרישות השפה והמיון.','לא ניתן לגשת למיון בפעם השלישית לאחר שתי דחיות. ניתנת עדיפות למי שסימנו את החוג בעדיפות ראשונה. היעדרות ללא הודעה וסיבה מוצדקת אינה מאפשרת ריאיון נוסף.','למחזור תשפ״ז: הפסיכומטרי ויע״ל עד אפריל 2026; הרשמה ומסמכים עד 14.06.2026. יש לבדוק את מועדי המחזור הבא לפני הרשמה.','לאחר קבלה נדרשים הצהרת בריאות והשלמת החיסונים למקצועות הבריאות עד סוף סמסטר א׳ בשנה א׳.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: occupational_therapy:haifa';
  END IF;
