  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='education:bgu' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['במסלול הדו־מחלקתי בבאר שבע: סכם 520 לפחות או פסיכומטרי 520 לפחות.','ללא פסיכומטרי: ממוצע בגרות 96 לפחות, בכפוף לדרישות השפה.','נדרשת אנגלית ברמת בסיסי ועברית ברמה ה׳ למי שחייבים בסיווג בעברית.','מכינה למדעים מדויקים והנדסה או למדעי הטבע והחיים של בן־גוריון בממוצע 70 יכולה להחליף את הבגרות באפיק זה.','אפשר לבקש דיון בחריגים עד 20 נקודות מתחת לסף הסכם או הפסיכומטרי, או עד 5 נקודות מתחת לממוצע הבגרות. נדרשות דרישות השפה, מכתב התאמה ומקום פנוי; האישור אינו אוטומטי.','מגיל 45 אפשר להתקבל ללא פסיכומטרי עם זכאות לבגרות ואנגלית ברמת בסיסי.','במסלול חינוך ראשי: פסיכומטרי 600 לפחות או בגרות 107 לפחות (או מכינה מתאימה בממוצע 89), ועמידה גם בתנאי החטיבה במדעי הטבע או במדעי המחשב.','במסלול הדו־מחלקתי בשילובים מסוימים, בעלי בגרות באנגלית 5 יחידות בציון 80 יכולים להשלים את סיווג האנגלית עד סוף סמסטר א׳: ניהול תיירות ופנאי, פילוסופיה, מזרח תיכון, אמנות ולימודי מדינת ישראל.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: education:bgu';
  END IF;
