  INSERT INTO source_urls (id,admission_requirement_id,program_id,institution_id,kind,url) VALUES ('nutrition:huji:program','nutrition:huji','nutrition','huji','program','https://info.huji.ac.il/bachelor/Nutrition-Sciences') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='ariel_economics:ariel' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ללא פסיכומטרי: ממוצע בגרות 92 לפחות. לחלופין, פסיכומטרי 600 לפחות וזכאות לבגרות, או ציון קבלה משולב 580 לפחות.','מתמטיקה: ציון עובר ב־4 או 5 יחידות, או 3 יחידות בציון 80. נדרשת בגרות מלאה עם 4 יחידות אנגלית בציון עובר.','נדרש סיווג אנגלית 85 לפחות. למי שסיימו תיכון או נבחנו בפסיכומטרי בשפה שאינה עברית נדרש יע״ל 120; ציונים 110–119 מאפשרים קבלה מותנית והשלמת קורס עברית בציון 75 עד סוף סמסטר א׳.','בחישוב המשולב נלקח הגבוה מבין הפסיכומטרי הרב־תחומי והכמותי. האוניברסיטה מעניקה תוספת לממוצע הבגרות לפי רמת המתמטיקה והציון.','קבלה מותנית לסמסטר אפשרית עם בגרות 85 לפחות, משולב 560–580, או מכינה בממוצע 80–85 ומתמטיקה 75. נדרש לסיים את קורסי סמסטר א׳ בממוצע 70 לפחות ובציון 60 לפחות בכל קורס.','קיימים אפיקים לבוגרי מכינות, הנדסאים, בעלי לימודים קודמים ולמועמדים מעל גיל 30. חוסר בדרישת המתמטיקה מחייב השלמה לפני הלימודים.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: ariel_economics:ariel';
  END IF;
  UPDATE admission_requirements SET specific_admission_notes=ARRAY['ללא פסיכומטרי: ממוצע בגרות 92 לפחות. לחלופין, פסיכומטרי 600 לפחות וזכאות לבגרות, או ציון קבלה משולב 580 לפחות.','מתמטיקה: ציון עובר ב־4 או 5 יחידות, או 3 יחידות בציון 80. נדרשת בגרות מלאה עם 4 יחידות אנגלית בציון עובר.','נדרש סיווג אנגלית 85 לפחות. למי שסיימו תיכון או נבחנו בפסיכומטרי בשפה שאינה עברית נדרש יע״ל 120; ציונים 110–119 מאפשרים קבלה מותנית והשלמת קורס עברית בציון 75 עד סוף סמסטר א׳.','בחישוב המשולב נלקח הגבוה מבין הפסיכומטרי הרב־תחומי והכמותי. האוניברסיטה מעניקה תוספת לממוצע הבגרות לפי רמת המתמטיקה והציון.','קבלה מותנית לסמסטר אפשרית עם בגרות 85 לפחות, משולב 560–580, או מכינה בממוצע 80–85 ומתמטיקה 75. נדרש לסיים את קורסי סמסטר א׳ בממוצע 70 לפחות ובציון 60 לפחות בכל קורס.','קיימים אפיקים לבוגרי מכינות, הנדסאים, בעלי לימודים קודמים ולמועמדים מעל גיל 30. חוסר בדרישת המתמטיקה מחייב השלמה לפני הלימודים.']::text[] WHERE id='ariel_economics:ariel';
  IF NOT EXISTS (SELECT 1 FROM source_urls WHERE id='ariel_economics:ariel:program' AND ((url IS NOT DISTINCT FROM 'https://www.ariel.ac.il/wp/registration-and-acceptance/') OR (url IS NOT DISTINCT FROM 'https://www.ariel.ac.il/wp/economics/%d7%aa%d7%a0%d7%90%d7%99-%d7%a7%d7%91%d7%9c%d7%94-%d7%91%d7%9b%d7%9c%d7%9b%d7%9c%d7%94-%d7%95%d7%9e%d7%a0%d7%94%d7%9c-%d7%a2%d7%a1%d7%a7%d7%99%d7%9d/'))) THEN
