  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='ariel_criminology:ariel' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ממוצע בגרות 90 לפחות, או ציון קבלה משולב 560 לפחות.','נדרשת זכאות לבגרות מלאה עם 4 יחידות אנגלית בציון עובר; ציון נמוך מחייב מכינת השלמה באנגלית.','נדרש סיווג אנגלית 85 לפחות. למי שסיימו תיכון או נבחנו בפסיכומטרי בשפה שאינה עברית נדרש יע״ל 120; ציונים 110–119 מאפשרים קבלה מותנית והשלמת קורס עברית בציון 75 עד סוף סמסטר א׳.','בתואר דו־חוגי יש לעמוד בתנאי הקבלה של שני החוגים.','קבלה מותנית לסמסטר אפשרית עם בגרות 85–90 או משולב 550–560. המעבר למעמד מן המניין מותנה בממוצע 70 ובציון 60 לפחות בכל קורס נדרש בסמסטר הראשון.','אפיק מעבר מהמחלקה הרב־תחומית: בגרות 80 לפחות לצורך דיון בבקשה; לאחר מכן סיום שנה א׳, כולל אנגלית, בממוצע 75 ובציון 70 לפחות בכל קורס. קיימים גם אפיקי מכינה, הנדסאים ולימודים קודמים.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: ariel_criminology:ariel';
  END IF;
