  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='nutrition:ariel' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ללא פסיכומטרי: בגרות 100 עם 9 יחידות ריאליות. חלופות: פסיכומטרי 580 ובגרות 90 עם 5 יחידות ריאליות, או ציון משולב 620 עם 9 יחידות ריאליות.','נדרשות 4 יחידות אנגלית בציון 80, 4 יחידות מתמטיקה בציון 75 ו־5 יחידות בביולוגיה, כימיה, פיזיקה או ביוטכנולוגיה. אפשר להשלים את דרישות האנגלית והמתמטיקה במכינה.','אין קבלה אוטומטית: נדרשים דיון בוועדה, קורות חיים והצהרת כוונות; ייתכנו ריאיון ומכינה בכימיה.','נדרש סיווג אנגלית 85 לפחות ויע״ל 120 למי שסיימו תיכון או נבחנו בפסיכומטרי בשפה שאינה עברית. בחישוב המשולב נלקח הגבוה מבין הפסיכומטרי הרב־תחומי והכמותי.','נדרשת הצהרת בריאות והשלמת החיסונים עד סוף סמסטר א׳ בשנה א׳. הקבלה לפי מקום פנוי והחלטת הוועדה; באתר מפורסמת רשימת המתנה.','קיימים אפיקים נוספים לבוגרי מכינות במדעים, לבעלי לימודים אקדמיים קודמים ולבוגרי תואר מדעי.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: nutrition:ariel';
