  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='ariel_psychology:ariel' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['במסלול החד־חוגי: בגרות 97 לפחות, או ציון קבלה משולב 580 לפחות.','אנגלית בבגרות: 4 יחידות בציון 80 או 5 יחידות בציון 70. מתמטיקה: 3 יחידות בציון 80 או 4–5 יחידות בציון 60 לפחות.','נדרש סיווג אנגלית 85 לפחות. למי שסיימו תיכון או נבחנו בפסיכומטרי בשפה שאינה עברית נדרש יע״ל 120; ציונים 110–119 מאפשרים קבלה מותנית והשלמת קורס עברית בציון 75 עד סוף סמסטר א׳.','קבלה מותנית לסמסטר אפשרית עם בגרות 87–97 או משולב 560–580. המעבר לסמסטר השני מחייב ממוצע 75 וציון 70 לפחות בכל קורס נדרש.','בחישוב המשולב נלקח הגבוה מבין הפסיכומטרי הרב־תחומי והכמותי. קיימים גם אפיקי מכינה, הנדסאים ולימודים קודמים; התנאים במסלול הדו־חוגי נבדקים בנפרד.']::text[]))) THEN
