  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='biu_psychology:biu' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['במסלול הדו־חוגי: סכם 75. במסלול החד־חוגי: סכם 75 וגם פסיכומטרי 680 לפחות.','נדרש ציון פסיכומטרי; הסכם משקלל אותו עם ממוצע הבגרות לפי חישוב בר־אילן.','אנגלית 85 לפחות. לפי הדרישות הכלליות המעודכנות, נדרש יע״ל 120 לחד־חוגי ו־105 לדו־חוגי, למי שחייבים בבחינה.','עדיפות לנבחנים בפסיכומטרי עד מועד מרץ–אפריל. עמוד המחלקה פורסם בפברואר 2025; את הסף למחזור המבוקש יש לאשר במחשבון הקבלה.','במסלול דו־חוגי יש לעמוד גם בתנאי החוג הנוסף. מעבר מדו־חוגי לחד־חוגי עם פסיכומטרי מעל 680 נעשה באמצעות הרשמה ורשימת המתנה.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: biu_psychology:biu';
  END IF;
