  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='biu_law:biu' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['ללא פסיכומטרי: בגרות 112 לפחות, אנגלית 5 יחידות בציון 90 וסיווג אנגלית 85 לפחות.','באפיק הפסיכומטרי: ציון 720 לפחות וזכאות לבגרות. קיים גם אפיק שמשקלל בגרות ופסיכומטרי לפי מחשבון הקבלה.','נדרשת אנגלית 85 לפחות ועברית 105 למי שחייבים בבחינת יע״ל לפי כללי האוניברסיטה.','לזכאים למסלול המילואים וכוחות הביטחון: בגרות 109 ואנגלית 5 יחידות בציון 80 או 4 יחידות בציון 90, בכפוף לתנאי הזכאות ולמכסה.','קיימים אפיקים לבעלי תואר קודם וללומדים באוניברסיטה הפתוחה, לפי החלטת ועדת הקבלה. למסלול המצטיינים נדרש גם ריאיון.','העמוד הרשמי מציין מועדי הרשמה ב־2026 וכותרות משנה משנים קודמות. יש לאשר את התנאים למחזור הבא לפני הרשמה.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: biu_law:biu';
  END IF;
