  UPDATE admission_requirements SET specific_admission_notes=ARRAY['בגרות בממוצע 80 לפחות, מכינה ייעודית בממוצע 80, או זכאות לבגרות ופסיכומטרי 520 לפחות.','מתמטיקה: 5 יחידות בציון 70 או 4 יחידות בציון 85 לפחות. ניתן להשלים במכינה או במבחן פטור בציון 80.','דיפלומת הנדסאי מוכרת בממוצע 80 עשויה להיחשב חלופה לבגרות. מעל גיל 30 ניתן לבדוק מכינת 30+ בציון 80, בכפוף למכסה וליתר הדרישות.','נדרש סיווג באנגלית. מי שלמדו בשפה שאינה עברית נדרשים לעמוד בדרישת עברית או להציג יע״ל לפי הנחיות המכללה.']::text[] WHERE id='mon_12341088622_cs:mon_12341088622';
