  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='haifa_politicalscience:haifa' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['סכם 580 ומעלה; 520–579 בטווח המתנה. חלופה ללא פסיכומטרי: בגרות מלאה בממוצע משוקלל 102 ומעלה.','אנגלית ברמת טרום־בסיסי לפחות. למי שנדרשים לסיווג עברית: 90 לפחות, בקבלה על תנאי עד להשלמה ל־120 בשנה א׳, או מעבר קורס עברית במכינה.','מסלול אופק: בגרות 75 ומעלה או מכינה בממוצע 75–84, ומעבר 2–4 קורסים בציון 76 לפחות בסמסטר הראשון, לפי מתכונת הלימודים. לבוגרי מכינת 30+ אפשרות למסלול זה ללא תלות בממוצע.','קבלה ישירה גם לבוגרי מכינת אוניברסיטת חיפה בממוצע 85 ומעלה, לבעלי תעודת הנדסאי מוכרת במה״ט עם ריאיון לפי הצורך, או לבעלי תואר קודם בממוצע 75 ומעלה.','בתוכנית הדו־שנתית נדרשים סכם 580, אנגלית ברמת בסיסי ועברית 120 לפחות.']::text[]))) THEN
