  IF NOT EXISTS (SELECT 1 FROM admission_requirements WHERE id='physiotherapy:tau' AND ((specific_admission_notes IS NOT DISTINCT FROM ARRAY[]::text[]) OR (specific_admission_notes IS NOT DISTINCT FROM ARRAY['פסיכומטרי 630 לפחות ובגרות מלאה או תואר ראשון מוכר. נדרש ציון עובר במתמטיקה ברמת 4 יחידות לפחות, או בדיקת קורס אקדמי במתמטיקה.','הקבלה מבוססת על סכם וריאיון אישי. העמידה בתנאי הסף מאפשרת מועמדות ואינה מבטיחה זימון לריאיון או קבלה.','אנגלית 120 לפחות בפסיכומטרי או אמירנט, או חלופה מוכרת של האוניברסיטה. לחייבים בעברית: יע״ל 105 עד ההרשמה ופטור עד תחילת שנה ב׳.','אזרחות ישראלית או תושבות קבע; הרשמה בעדיפות ראשונה ולשנה א׳ בלבד. אין קבלה על תנאי.','חלופות לבגרות בחישוב הסכם: מכינה במדעי הטבע או המדעים המדויקים בממוצע 85, לימודים אקדמיים בהיקף 40 שעות סמסטריאליות בממוצע 80, או תואר קודם בממוצע 80, בהתאם לכללי המחלקה.','לא תישקל מועמדות של מי שנכשלו או הורחקו מלימודי רפואה או מקצועות הבריאות. ועדת הקבלה רשאית לדון בחריגים.']::text[]))) THEN
    RAISE EXCEPTION 'Content changed since review: physiotherapy:tau';
  END IF;
