  UPDATE admission_requirements SET specific_admission_notes=ARRAY['בגרות מלאה או תעודה שוות ערך ובחינות כניסה של המחלקה. ברוב המחלקות אין דרישת פסיכומטרי; באדריכלות נוף נדרשים גם תנאי האוניברסיטה העברית.','אנגלית ברמת בסיסי, ציון 85 לפחות באמירנט או בפרק האנגלית בפסיכומטרי. התחלה ללא הרמה הנדרשת מותנית באישור ועדה.','ללא בגרות ישראלית נדרש סיווג עברית: פטור ברמה ה׳ או יע״ל 100. אפשר להתחיל לאחר סיום רמה ג׳ ולהשלים פטור עד סוף שנה א׳.','תעודות חלופיות כוללות מכינה מוכרת, בגרות מחו״ל עם אישור שקילות, הנדסאי או מבחני סאלד עם תעודת מורה בכיר. בתרבות חזותית וחומרית נדרש ממוצע בגרות 85.','באדריכלות נוף: דרישות בגרות ופסיכומטרי של הפקולטה לחקלאות באוניברסיטה העברית, אנגלית בסיסי ועברית ברמת הפטור למי שנדרשים לכך. הענקת התואר מותנית באישור המל״ג.']::text[] WHERE id='bezalel_graphic_design:bezalel';
